import json
import os
from pathlib import Path
from typing import Dict, List

from .models import Book, Member, Loan

class Storage:
    def __init__(self, db_path: str):
        self.db_path = Path(db_path)
        self.data: Dict[str, List[Dict]] = {
            "books": [],
            "members": [],
            "loans": [],
            "return_fees": [],  # list of dicts: {"member_id": str, "fee": float}
            "borrow_history": [],  # list of dicts: {"isbn": str, "member_id": str, "borrow_date": str}
        }
        self._load()

    def _load(self):
        if self.db_path.exists():
            with self.db_path.open("r", encoding="utf-8") as f:
                try:
                    raw = json.load(f)
                except json.JSONDecodeError:
                    raw = {}
            # Ensure all keys present
            for key in self.data:
                self.data[key] = raw.get(key, [])
        else:
            # No file, start empty
            pass

    def _save(self):
        with self.db_path.open("w", encoding="utf-8") as f:
            json.dump(self.data, f, indent=2, sort_keys=True)

    # CRUD helpers
    def add_book(self, book: Book):
        if any(b["isbn"] == book.isbn for b in self.data["books"]):
            raise ValueError(f"Book with ISBN {book.isbn} already exists")
        self.data["books"].append(book.__dict__)
        self._save()

    def add_member(self, member: Member):
        if any(m["member_id"] == member.member_id for m in self.data["members"]):
            raise ValueError(f"Member with ID {member.member_id} already exists")
        self.data["members"].append(member.__dict__)
        self._save()

    def get_book(self, isbn: str) -> Book:
        for b in self.data["books"]:
            if b["isbn"] == isbn:
                return Book(**b)
        raise KeyError(f"Book {isbn} not found")

    def get_member(self, member_id: str) -> Member:
        for m in self.data["members"]:
            if m["member_id"] == member_id:
                return Member(**m)
        raise KeyError(f"Member {member_id} not found")

    def add_loan(self, loan: Loan):
        if any(l["isbn"] == loan.isbn for l in self.data["loans"]):
            raise ValueError(f"Book {loan.isbn} already on loan")
        self.data["loans"].append(loan.__dict__)
        self.data["borrow_history"].append({"isbn": loan.isbn, "member_id": loan.member_id, "borrow_date": loan.borrow_date})
        self._save()

    def remove_loan(self, isbn: str) -> Loan:
        for i, l in enumerate(self.data["loans"]):
            if l["isbn"] == isbn:
                loan = Loan(**l)
                del self.data["loans"][i]
                self._save()
                return loan
        raise KeyError(f"Loan for ISBN {isbn} not found")

    def add_return_fee(self, member_id: str, fee: float):
        self.data["return_fees"].append({"member_id": member_id, "fee": fee})
        self._save()

    def list_loans(self) -> List[Loan]:
        return [Loan(**l) for l in self.data["loans"]]

    def list_books(self) -> List[Book]:
        return [Book(**b) for b in self.data["books"]]

    def list_members(self) -> List[Member]:
        return [Member(**m) for m in self.data["members"]]

    def list_borrow_history(self) -> List[Dict]:
        return self.data["borrow_history"].copy()

    def list_return_fees(self) -> List[Dict]:
        return self.data["return_fees"].copy()
