from datetime import datetime
from typing import Tuple

from .models import Book, Member, Loan
from .storage import Storage
from .rules import calculate_due_date, calculate_late_fee, MAX_ACTIVE_LOANS

class LibraryError(Exception):
    pass

class Library:
    def __init__(self, storage: Storage):
        self.storage = storage

    def borrow(self, member_id: str, isbn: str, date: str) -> None:
        # Validate member and book exist
        try:
            member = self.storage.get_member(member_id)
        except KeyError as e:
            raise LibraryError(str(e))
        try:
            book = self.storage.get_book(isbn)
        except KeyError as e:
            raise LibraryError(str(e))

        # Check active loans for member
        active_loans = [l for l in self.storage.list_loans() if l.member_id == member_id]
        if len(active_loans) >= MAX_ACTIVE_LOANS:
            raise LibraryError(f"Member {member_id} has reached the maximum active loans ({MAX_ACTIVE_LOANS})")

        # Check book not already on loan
        if any(l.isbn == isbn for l in self.storage.list_loans()):
            raise LibraryError(f"Book {isbn} is already on loan")

        due_date = calculate_due_date(date)
        loan = Loan(isbn=isbn, member_id=member_id, borrow_date=date, due_date=due_date)
        self.storage.add_loan(loan)

    def return_book(self, isbn: str, date: str) -> float:
        # Find loan
        try:
            loan = self.storage.remove_loan(isbn)
        except KeyError as e:
            raise LibraryError(str(e))

        fee = calculate_late_fee(loan.due_date, date)
        self.storage.add_return_fee(loan.member_id, fee)
        return fee
